 25	const CANARY = 'obs007-stale-grant-A-é:+/';
 26	const CLEANUP_MS = 5000;
 27	type Label = 'A' | 'PROBE' | 'B';
 28	type Scalar = string | number | boolean | null;
 29	type Fact = Record<string, Scalar>;
 30	interface CleanupFact {label: string; confirmed: boolean}
 31	interface Client {
 32	  label: Label;
 33	  context: ReturnType<typeof guidedContext>;
 34	  grant: ReturnType<typeof ownershipSession>;
 35	  assignment: ReturnType<typeof assignmentFor>;
 36	  evidence?: ExecutionEvidence;
 37	  observation?: BridgeObservation['observation'];
 38	  scratch?: string;
 39	  preferences?: BrowserPreferenceEvidence;
 40	  sdk?: WeakRef<BrowserContext>;
 41	  sdkRestores: (() => void)[];
 42	  launchAttempts: number;
 43	  launches: number;
 44	  starts: number;
 45	  dispatches: number;
 46	  nativeEntries: number;
 47	  nativePending: number;
 48	  closed: boolean;
 49	}
 50	interface InventoryView {values: Map<string, boolean>; bytes: number; disposed: boolean; failed: boolean}
 51	const responseCodes = new Set(['CONTEXT_LOST', 'IDENTITY_MISMATCH', 'LEASE_LOST', 'SCHEMA', 'CAPACITY', 'AUTH_DENIED', 'TARGET_CHANGED', 'POLICY_DENIED', 'IDEMPOTENCY_CONFLICT']);
 52	function code(body: unknown): string {
 53	  return typeof body === 'object' && body !== null && 'code' in body && typeof body.code === 'string' && responseCodes.has(body.code) ? body.code : 'OTHER';
 54	}
 55	function status(reply: Awaited<ReturnType<typeof post>>, expected: number): void {expect(reply.status, code(reply.body)).toBe(expected);}
 56	function* patterns(): Generator<readonly [string, Buffer]> {
 57	  yield ['UTF8-NFC', Buffer.from(CANARY.normalize('NFC'))]; yield ['UTF8-NFD', Buffer.from(CANARY.normalize('NFD'))];
 58	  yield ['URI', Buffer.from(encodeURIComponent(CANARY))]; yield ['URI-TWICE', Buffer.from(encodeURIComponent(encodeURIComponent(CANARY)))];
 59	  yield ['UTF16-LE', Buffer.from(CANARY, 'utf16le')]; yield ['UTF16-BE', Buffer.from(CANARY, 'utf16le').swap16()];
 60	  yield ['HEX-LOWER', Buffer.from(Buffer.from(CANARY).toString('hex'))]; yield ['HEX-UPPER', Buffer.from(Buffer.from(CANARY).toString('hex').toUpperCase())];
 61	  yield ['BASE64', Buffer.from(Buffer.from(CANARY).toString('base64'))];
 62	  yield ['JSON-UNICODE', Buffer.from(CANARY.replace(/[^\u0020-\u007e]/gu, char => '\\u' + char.charCodeAt(0).toString(16).padStart(4, '0')))];
 63	}
 64	function hits(bytes: Uint8Array): number {
 65	  let count = 0; const view = Buffer.from(bytes.buffer, bytes.byteOffset, bytes.byteLength);
 66	  for (const [, pattern] of patterns()) if (view.includes(pattern)) count++; return count;
 67	}
 68	/** Only numeric prefixes/counters survive a write; no output chunks/tails are retained. */
 69	function outputWitness() {
 70	  const prefixes: Record<string, number> = {}, counts: Record<string, number> = {}, observed: Record<string, number> = {};
 71	  return {
 72	    counts, observed,
 73	    total: () => Object.values(counts).reduce((sum, count) => sum + count, 0),
 74	    observe(sink: string, chunk: unknown, encoding?: unknown): void {
 75	      const bytes = typeof chunk === 'string' ? Buffer.from(chunk, typeof encoding === 'string' && Buffer.isEncoding(encoding) ? encoding : undefined) : chunk instanceof Uint8Array ? chunk : null;
 76	      if (!bytes) return;
 77	      observed[sink + '-calls'] = (observed[sink + '-calls'] ?? 0) + 1; observed[sink + '-bytes'] = (observed[sink + '-bytes'] ?? 0) + bytes.byteLength;
 78	      for (const [variant, pattern] of patterns()) {
 79	        const key = sink + '/' + variant; let matched = prefixes[key] ?? 0;
 80	        for (const byte of bytes) {
 81	          while (matched > 0 && byte !== pattern[matched]) {
 82	            let next = matched - 1; while (next > 0 && !pattern.subarray(0, next).equals(pattern.subarray(matched - next, matched))) next--; matched = next;
 83	          }
 84	          if (byte === pattern[matched]) matched++;
 85	          if (matched === pattern.length) {counts[key] = (counts[key] ?? 0) + 1; matched = 0;}
 86	        }
 87	        prefixes[key] = matched;
 88	      }
 89	    },
 90	  };
 91	}
 92	function patch(holder: object, key: string, observe: (receiver: object, args: unknown[], invoke: () => unknown) => unknown): () => void {
 93	  const own = Object.getOwnPropertyDescriptor(holder, key), original = Reflect.get(holder, key) as (...args: unknown[]) => unknown;
 94	  if (typeof original !== 'function') throw Error('METHOD');
 95	  Object.defineProperty(holder, key, {configurable: true, writable: true, value: new Proxy(original, {apply(target, receiver, args) {return observe(receiver as object, args, () => Reflect.apply(target, receiver, args));}})});
 96	  return () => {if (own) Object.defineProperty(holder, key, own); else if (!Reflect.deleteProperty(holder, key)) throw Error('DESCRIPTOR_RESTORE_UNCONFIRMED');};
 97	}
 98	function restore(list: (() => void)[], label: string, cleanup: CleanupFact[]): boolean {
 99	  let confirmed = true;
100	  for (const release of [...list].reverse()) try {release(); const at = list.lastIndexOf(release); if (at >= 0) list.splice(at, 1);} catch {cleanup.push({label, confirmed: false}); confirmed = false;}
101	  return confirmed;
102	}
103	async function bounded(label: string, release: () => Promise<unknown>, deadline: number, cleanup: CleanupFact[]): Promise<void> {
104	  let pending: Promise<unknown>; try {pending = release();} catch {cleanup.push({label, confirmed: false}); return;}
105	  let timer: ReturnType<typeof setTimeout> | undefined;
106	  const confirmed = await Promise.race([pending.then(() => true, () => false), new Promise<boolean>(done => {timer = setTimeout(() => {done(false);}, Math.max(0, deadline - performance.now()));})]);
107	  if (timer) clearTimeout(timer); cleanup.push({label, confirmed});
108	}
109	function scanSync(root: string): number {
110	  let count = 0; for (const item of readdirSync(root, {withFileTypes: true})) {
111	    const path = join(root, item.name); if (item.isDirectory()) count += scanSync(path);
112	    else if (item.isFile()) count += hits(readFileSync(path));
113	  } return count;
114	}
115	async function scan(root: string): Promise<number> {
116	  let count = 0; for (const item of await readdir(root, {withFileTypes: true})) {
117	    const path = join(root, item.name); if (item.isDirectory()) count += await scan(path);
118	    else if (item.isFile()) count += hits(await readFile(path));
119	  } return count;
120	}
