122	it('rejects the genuine retired CSI-A grant for a fresh CSI-B assignment before context or secret effects', async () => {
123	  const resources: {label: string; release: () => Promise<unknown>}[] = [], restorers: (() => void)[] = [], cleanup: CleanupFact[] = [], facts: Fact[] = [], pids: {label: Label; pid: number}[] = [];
124	  const clients = new Map<string, Client>(), setup = new Map<Label, Promise<void>>(), output = outputWitness(), inventoryTags = new WeakMap<object, number>(), inventoryOwners = new WeakMap<object, Label>();
125	  let nextInventory = 0, launching: Label = 'A', journal: string | undefined, fixture: Awaited<ReturnType<typeof startSecretLoginFixture>> | undefined, worker: ReturnType<typeof createGuidedServer> | undefined, workerPort = 0;
126	  // The sole retained authority is the names-only grant returned by original checkGrant.
127	  // No private runtime/inventory arrays or secret values are captured from its arguments.
128	  let acceptedA: Session | null = null, primaryFailed = false, cleaning = false;
129	  function scanOwned(root: string, label: string, phase: string, required = false): void {
130	    if (!existsSync(root)) {facts.push({kind: 'scan', label, phase, scanned: false, hits: null, status: 'UNAVAILABLE_UNSCANNED'}); if (required) cleanup.push({label: 'required-root-unscanned', confirmed: false}); return;}
131	    try {const count = scanSync(root); facts.push({kind: 'scan', label, phase, scanned: true, hits: count, status: 'SCANNED'}); if (count > 0) cleanup.push({label: 'profile-or-journal-canary', confirmed: false});}
132	    catch {facts.push({kind: 'scan', label, phase, scanned: false, hits: null, status: 'UNAVAILABLE_UNSCANNED'}); cleanup.push({label: 'root-scan', confirmed: false});}
133	  }
