147	    const grant = ownershipSession(context); grant.scope.csiId = csiId; grant.scopeHash = hash(grant.scope); grant.runAuthorization.scopeHash = grant.scopeHash;
148	    context.scopeHash = grant.scopeHash; context.authoredInputs.scopeHash = grant.scopeHash; context.authoredInputsHash = hash(context.authoredInputs); context.leaseExpiresAt = grant.owner.leaseExpiresAt;
149	    const client: Client = {label, context, grant, assignment: assignmentFor(context), sdkRestores: [], launchAttempts: 0, launches: 0, starts: 0, dispatches: 0, nativeEntries: 0, nativePending: 0, closed: false};
150	    clients.set(context.sessionId, client); return client;
151	  }
152	  const route = (client: Client): string => '/internal/v2/studio/guided-sessions/' + client.context.sessionId;
153	  async function action(client: Client, step: string, operation: Action['operation'], target?: Action['target'], secret?: string): Promise<void> {
154	    if (!client.evidence || !fixture) throw Error('EVIDENCE'); const proposed = proposal(client.context, client.evidence, step, operation, target);
155	    const prepared = await post(workerPort, route(client) + '/prepare', {...identity(client.context), proposal: proposed, requestDigest: hash(proposed), expiresAt: client.context.expiresAt}, {key: client.label + '-prepare-' + step}); status(prepared, 200);
156	    const request = dispatch(client.context, proposed, validate<BridgePreparation>('bridge', prepared.body, 'preparation'));
157	    const frame = secret === undefined ? request : {...request, secret: {secretId: 'PASS', value: secret, versionId: 'fixture-version', allowedOrigins: [fixture.origin]}};
158	    let reply: Awaited<ReturnType<typeof post>>; try {reply = await post(workerPort, route(client) + '/dispatch', frame, {key: client.label + '-dispatch-' + step});} finally {if ('secret' in frame) delete (frame as {secret?: unknown}).secret;}
159	    status(reply, 200); const outcome = validate<BridgeOutcome>('bridge', reply.body, 'outcome'); expect(outcome.ledger.state).toBe('SUCCEEDED'); expect(hits(Buffer.from(JSON.stringify(outcome)))).toBe(0);
160	  }
161	  async function stop(client: Client): Promise<void> {
162	    scanExtant(); status(await post(workerPort, route(client) + '/stop', {...identity(client.context), reason: 'CANCELLED'}, {key: client.label + '-stop'}), 200);
163	    await untilMs(() => client.closed && pids.filter(pid => pid.label === client.label).every(pid => !isAlive(pid.pid)), CLEANUP_MS);
164	    expect(client.scratch !== undefined && !existsSync(client.scratch)).toBe(true);
165	  }
166	  try {
167	    for (const name of ['DEBUG', 'PWDEBUG', 'NODE_DEBUG', 'NODE_OPTIONS']) expect(Boolean(process.env[name])).toBe(false);
168	    fixture = await startSecretLoginFixture(CANARY); const ownedFixture = fixture; resources.push({label: 'fixture', release: ownedFixture.close});
169	    journal = await mkdtemp(join(tmpdir(), 'guided-stale-grant-')); const ownedJournal = journal; resources.push({label: 'journal', release: () => rm(ownedJournal, {recursive: true, force: true})});
170	    resources.push({label: 'descriptors', release: () => restoreAll() ? Promise.resolve() : Promise.reject(Error('DESCRIPTOR_RESTORE_UNCONFIRMED'))});
171	    for (const [sink, stream] of [['stdout', process.stdout], ['stderr', process.stderr]] as const) restorers.push(patch(stream, 'write', (_receiver, args, invoke) => {output.observe(sink, args[0], args[1]); return invoke();}));
