186	      const runtime = receiver as GuidedRuntime, client = requireClient(runtime.currentIdentity.sessionId); if (method === 'start') client.starts++; else client.dispatches++;
187	      facts.push({kind: 'runtime-entry', label: client.label, method, at: performance.now()}); return invoke();
