190	      const view = receiver as InventoryView; let tag = inventoryTags.get(receiver); if (tag === undefined) {tag = ++nextInventory; inventoryTags.set(receiver, tag); inventoryOwners.set(receiver, launching);}
191	      const observedTag = tag;
192	      const record = (phase: string): void => {facts.push({kind: 'inventory', label: inventoryOwners.get(receiver) ?? 'UNKNOWN', tag: observedTag, method, phase, size: view.values.size, bytes: view.bytes, containsA: view.values.has(CANARY), disposed: view.disposed, failed: view.failed});};
193	      record('before'); const returned = invoke(); record('after'); return returned;
194	    }));
195	    restorers.push(patch(chromium, 'launchPersistentContext', (_receiver, args, invoke) => {
196	      const client = [...clients.values()].find(value => value.label === launching); if (!client) throw Error('CLIENT');
197	      const scratch = typeof args[0] === 'string' && basename(args[0]) === 'browser-profile' ? dirname(args[0]) : null; if (scratch) client.scratch = scratch;
198	      client.launchAttempts++; const before = descendantsOf(process.pid);
199	      let original: Promise<BrowserContext>; try {original = invoke() as Promise<BrowserContext>;} catch (error) {if (scratch) scanOwned(scratch, client.label, 'SDK-sync-reject', true); throw error;}
200	      const prepared = original.then(async context => {
201	        if (cleaning) {await bounded('late-context', () => context.close(), performance.now() + CLEANUP_MS, cleanup); throw Error('CONTEXT_LOST');}
